def parse_field_boosts(field_boosts: str) -> Dict[str, float]:
    field_boost_dict = defaultdict(float)
    for field_boost in field_boosts.split(";"):
        if ":" in field_boost:
            field, boost = field_boost.split(":")
            field_boost_dict[field] = float(boost)
        else:
            field_boost_dict[field_boost] = 1.0
    return dict(field_boost_dict)

def parse_query_terms(frame: pd.DataFrame,
                      q: str,
                      qf: List[str]) -> Tuple[int, Dict[str, List[str]], bool]:
    qf_dict = parse_field_boosts(qf[0])
    terms_per_field = defaultdict(list)
    num_search_terms = 0
    term_centric = False

    for field in qf_dict:
        if field in qf[1:]:
            boost = qf_dict[field]
        else:
            boost = 1.0

        for token in word_tokenize(q):
            if token.lower() in frame[field].tolist():
                terms_per_field[field].append((token, boost))
                num_search_terms += 1

    if num_search_terms > 0:
        term_centric = len(terms_per_field) == 1

    return num_search_terms, terms_per_field, term_centric

